<script setup lang="ts">import EmployeeSearchSelect from '../../Components/EmployeeSearchSelect.vue';import {Head,useForm} from '@inertiajs/vue3';import AdminLayout from '@core/Layouts/AdminLayout.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';import {Label} from '@/components/ui/label';import DataTable,{type DataTableColumn} from '@core/Components/DataTable.vue';import type {Paginator, SelectOption } from '@core/types';const p=defineProps<{configuration:any;employeeOptions:SelectOption[];profiles:Paginator<any>;auditEvents:Paginator<any>}>();const f=useForm({name:p.configuration.name,mode:p.configuration.mode,fixed_monthly_tax:Number(p.configuration.fixed_monthly_tax),annual_exemption:Number(p.configuration.annual_exemption),taxable_salary_percent:Number(p.configuration.taxable_salary_percent),effective_from:p.configuration.effective_from||'',effective_to:p.configuration.effective_to||'',reason:'',slabs:p.configuration.slabs?.map((s:any)=>({lower_limit:Number(s.lower_limit),upper_limit:s.upper_limit?Number(s.upper_limit):'',rate_percent:Number(s.rate_percent)}))||[]});const profile=useForm({employee_id:'',override_mode:'global_config',fixed_tax_amount:0,fixed_tax_frequency:'monthly',exemption_reason:'',reason:'',effective_from:new Date().toISOString().slice(0,10),effective_to:''});function save(){f.put(route('payroll.tax.update'))}function saveProfile(){profile.post(route('payroll.tax.profiles.store'))}function looseProfileErrors(){return Object.entries(profile.errors).filter(([k])=>!['employee_id','override_mode','fixed_tax_amount','exemption_reason','reason','effective_from','effective_to'].includes(k)).map(([,m])=>String(m))}function addSlab(){f.slabs.push({lower_limit:0,upper_limit:'',rate_percent:0})}function removeSlab(i:number){f.slabs.splice(i,1)}const profileColumns:DataTableColumn[]=[{key:'employee_id',label:'Employee'},{key:'override_mode',label:'Override'},{key:'fixed_tax_amount',label:'Fixed tax'},{key:'effective_from',label:'Effective from'},{key:'effective_to',label:'Effective to'}];</script><template><AdminLayout :breadcrumbs="[{ title: 'Payroll' }, { title: 'Tax & profiles' }]"><Head title="Payroll tax"/><div class="grid gap-6 xl:grid-cols-[1.2fr_0.8fr]"><div class="rounded-xl border bg-card p-5"><h1 class="text-xl font-bold">Annual tax configuration</h1><p class="mt-1 text-sm text-muted-foreground">Admin-maintained annual slabs are applied to annualized monthly taxable income; withholding is annual liability divided by 12. Policy/profile versions and before/after reasons are retained.</p><form @submit.prevent="save" class="mt-5 space-y-4"><div class="space-y-2"><Label>Configuration name</Label><Input v-model="f.name"/></div><div class="grid grid-cols-2 gap-4"><div><Label>Mode</Label><select v-model="f.mode" class="h-10 w-full rounded-md border bg-background px-3"><option value="progressive">Progressive annual slabs</option><option value="fixed">Fixed monthly amount</option></select></div><div><Label>Fixed monthly tax</Label><Input v-model.number="f.fixed_monthly_tax" type="number" min="0" step="0.01"/></div></div><div class="grid grid-cols-2 gap-4"><div><Label>Annual exemption</Label><Input v-model.number="f.annual_exemption" type="number" min="0" step="0.01"/></div><div><Label>Taxable salary %</Label><Input v-model.number="f.taxable_salary_percent" type="number" min="0" max="100" step="0.01"/></div></div><div class="grid grid-cols-2 gap-4"><div><Label>Effective from</Label><Input v-model="f.effective_from" type="date"/><p v-if="f.errors.effective_from" class="text-xs text-destructive">{{f.errors.effective_from}}</p></div><div><Label>Effective to (optional)</Label><Input v-model="f.effective_to" type="date"/><p v-if="f.errors.effective_to" class="text-xs text-destructive">{{f.errors.effective_to}}</p></div></div><div><Label>Reason for policy change (required)</Label><textarea v-model="f.reason" required minlength="3" maxlength="1000" class="min-h-16 w-full rounded-md border bg-background p-2"/><p v-if="f.errors.reason" class="text-xs text-destructive">{{f.errors.reason}}</p></div><div class="space-y-2"><div class="flex items-center justify-between"><Label>Progressive slabs (annual limits)</Label><Button type="button" variant="outline" size="sm" @click="addSlab">Add slab</Button></div><div v-for="(slab,i) in f.slabs" :key="i" class="grid grid-cols-[1fr_1fr_0.7fr_auto] gap-2"><Input v-model.number="slab.lower_limit" type="number" placeholder="From"/><Input v-model="slab.upper_limit" type="number" placeholder="To (blank = unlimited)"/><Input v-model.number="slab.rate_percent" type="number" placeholder="Rate %"/><Button type="button" variant="ghost" @click="removeSlab(i)">×</Button></div><p v-if="f.errors.slabs" class="text-sm text-destructive">{{f.errors.slabs}}</p></div><Button :disabled="f.processing">Save configuration</Button></form></div><div class="space-y-5"><div class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Employee tax override</h2><p class="mt-1 text-xs text-muted-foreground">Nothing needs allocating: every employee follows the annual configuration above unless an override exists here — <strong>{{profiles.meta.total}}</strong> on file. Depositing what payroll withheld is a separate desk — <strong>Accounts → TDS / VDS Withholding → Deposits</strong> — where the amounts are allocated to one treasury challan per tax type.</p><form @submit.prevent="saveProfile" class="mt-4 space-y-3"><div><Label>Employee</Label><EmployeeSearchSelect v-model="profile.employee_id" :options="employeeOptions"/><p v-if="profile.errors.employee_id" class="text-xs text-destructive">{{profile.errors.employee_id}}</p></div><div><Label>Mode</Label><select v-model="profile.override_mode" class="h-10 w-full rounded-md border bg-background px-3"><option value="global_config">Use global rules</option><option value="force_fixed">Force fixed tax</option><option value="exempt">Exempt</option></select></div><div v-if="profile.override_mode==='force_fixed'"><Label>Fixed amount</Label><Input v-model.number="profile.fixed_tax_amount" type="number" min="0" step="0.01"/><select v-model="profile.fixed_tax_frequency" class="mt-2 h-10 w-full rounded-md border bg-background px-3"><option value="monthly">Monthly</option><option value="annual">Annual</option></select></div><div v-if="profile.override_mode==='exempt'"><Label>Exemption legal/HR basis</Label><textarea v-model="profile.exemption_reason" required minlength="3" class="min-h-16 w-full rounded-md border bg-background p-2"/><p v-if="profile.errors.exemption_reason" class="text-xs text-destructive">{{profile.errors.exemption_reason}}</p></div><div><Label>Reason for profile change (required)</Label><textarea v-model="profile.reason" required minlength="3" class="min-h-16 w-full rounded-md border bg-background p-2"/><p v-if="profile.errors.reason" class="text-xs text-destructive">{{profile.errors.reason}}</p></div><ul v-if="looseProfileErrors().length" class="rounded-md bg-amber-500/10 p-2 text-xs text-amber-900 dark:text-amber-200"><li v-for="(message,i) in looseProfileErrors()" :key="i">{{message}}</li></ul><Button :disabled="profile.processing">Save employee profile</Button></form></div><div class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Employee tax profiles</h2><DataTable class="mt-3" route-name="payroll.tax.index" title="Tax profiles" :columns="profileColumns" :rows="profiles.data" :meta="profiles.meta"><template #cell-employee_id="{row}"><strong>{{row.employee_name||row.employee_id}}</strong><span class="block text-xs text-muted-foreground">{{row.employee_id}}</span></template><template #cell-override_mode="{row}">{{row.override_mode.replaceAll('_',' ')}}</template></DataTable></div><section class="rounded-xl border bg-card p-5"><h2 class="font-semibold">Tax change audit trail</h2><div class="mt-3 divide-y"><article v-for="event in auditEvents.data" :key="event.id" class="py-3 text-sm"><div class="flex flex-wrap justify-between gap-2"><strong>{{event.event_type.replaceAll('_',' ')}} · {{event.employee_id||('configuration #'+event.after?.id)}}</strong><span class="text-xs text-muted-foreground">{{event.actor}} · {{new Date(event.occurred_at).toLocaleString()}}</span></div><p class="mt-1 text-xs text-muted-foreground">Reason: {{event.reason||'—'}}</p><details class="mt-2"><summary class="cursor-pointer text-xs text-primary">View before/after snapshot</summary><div class="mt-2 grid gap-2 md:grid-cols-2"><pre class="max-h-48 overflow-auto whitespace-pre-wrap rounded bg-muted p-2 text-[10px]">Before: {{JSON.stringify(event.before||{},null,2)}}</pre><pre class="max-h-48 overflow-auto whitespace-pre-wrap rounded bg-muted p-2 text-[10px]">After: {{JSON.stringify(event.after||{},null,2)}}</pre></div></details></article><p v-if="!auditEvents.data.length" class="py-4 text-sm text-muted-foreground">No tax changes have been recorded.</p></div></section></div></div></AdminLayout></template>